insert into public.inventory_members values('11111111-1111-4111-8111-111111111111','Operador A');
create function public.expect_rejection(sql text) returns void language plpgsql as $$
declare rejected boolean:=false;
begin
  begin execute sql; exception when others then rejected:=true; end;
  if not rejected then raise exception 'Operação indevida aceita: %',sql; end if;
end $$;
set role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',false);
select public.expect_rejection('select public.inventory_snapshot()');
select public.test_assert((select count(*) from public.inventory_sheets)=0,'RLS não expõe estoque a usuário sem autorização');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',false);
select public.test_assert(jsonb_array_length(public.inventory_snapshot()->'sheets')=14,'14 combinações iniciais');
select public.expect_rejection('update public.inventory_sheets set quantity=10');
select public.expect_rejection('delete from public.inventory_events');
select public.inventory_apply('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','sheet_move','{"id":"carbono-2","delta":3}');
select public.inventory_apply('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','sheet_move','{"id":"carbono-2","delta":3}');
select public.test_assert((select quantity from public.inventory_sheets where id='carbono-2')=3 and (select count(*) from public.inventory_events)=1,'repetição não duplica saldo nem auditoria');
select public.expect_rejection($q$select public.inventory_apply('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','sheet_move','{"id":"carbono-2","delta":4}')$q$);
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'sheet_move','{"id":"carbono-2","delta":-4}')$q$);
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'sheet_move','{"id":"carbono-2","delta":0.5}')$q$);
select public.test_assert((select quantity from public.inventory_sheets where id='carbono-2')=3,'baixa excessiva e frações rejeitadas');
select public.inventory_apply(gen_random_uuid(),'scrap_add','{"catalog_id":"carbono-2","width":300,"length":500,"quantity":2,"code":"R-001"}');
select public.expect_rejection(format($q$select public.inventory_apply(gen_random_uuid(),'scrap_consume',%L)$q$,jsonb_build_object('id',(select id from public.inventory_scraps limit 1),'quantity',1,'revision',1,'remainder',jsonb_build_object('width',600,'length',600,'code','R-bad'))));
select public.test_assert((select quantity from public.inventory_scraps limit 1)=2,'sobra inválida reverte consumo inteiro');
select public.inventory_apply(gen_random_uuid(),'scrap_consume',jsonb_build_object('id',(select id from public.inventory_scraps limit 1),'quantity',1,'revision',1,'remainder',jsonb_build_object('width',200,'length',300,'code','R-002')));
select public.test_assert((select count(*) from public.inventory_scraps)=2 and (select quantity from public.inventory_scraps where code='R-001')=1,'consumo parcial gera sub-retalho vinculado');
select public.inventory_apply(gen_random_uuid(),'task_save',jsonb_build_object('id','task-a','task',public.test_task('task-a'),'revision',0));
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'task_save',jsonb_build_object('id','task-a','task',public.test_task('task-a'),'revision',0))$q$);
select public.inventory_apply(gen_random_uuid(),'task_save',jsonb_build_object('id','task-a','task',public.test_task('task-a')||'{"status":"completed"}'::jsonb,'revision',(select revision from public.inventory_tasks where id='task-a')));
select public.test_assert((select payload->>'completedAt' from public.inventory_tasks where id='task-a') is not null,'conclusão recebe horário do servidor');
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'task_replace','{"tasks":[],"revision":0}')$q$);
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'task_import',jsonb_build_object('tasks',jsonb_build_array(public.test_task('valid'),'{"id":"invalid"}'::jsonb)))$q$);
select public.test_assert(not exists(select 1 from public.inventory_tasks where id='valid'),'importação inválida reverte todas as atividades');
select set_config('test.old_revision',(select revision::text from public.inventory_tasks where id='task-a'),false);
select public.inventory_apply(gen_random_uuid(),'task_replace',jsonb_build_object('tasks',jsonb_build_array(public.test_task('task-a')),'revision',(select revision from public.inventory_state)));
select public.test_assert((select revision from public.inventory_tasks where id='task-a')>current_setting('test.old_revision')::bigint,'restauração não reutiliza revisões anteriores');
select public.expect_rejection(format($q$select public.inventory_apply(gen_random_uuid(),'task_save',jsonb_build_object('id','task-a','task',public.test_task('task-a'),'revision',%s))$q$,current_setting('test.old_revision')));
select public.test_assert((select bool_and(actor_name='Operador A' and actor_id='11111111-1111-4111-8111-111111111111') from public.inventory_events),'autoria determinada pela sessão no servidor');
set role anon;
select public.expect_rejection('select public.inventory_snapshot()');
select public.expect_rejection($q$select public.inventory_apply(gen_random_uuid(),'sheet_move','{"id":"carbono-2","delta":10}')$q$);
reset role;
